export const exercises=rows.map(([id,name,pattern,equipment,primary,secondary,stabilizers,difficulty,category,execution,aliases])=>({id,name,pattern,equipment:split(equipment),primary:split(primary),secondary:split(secondary),stabilizers:split(stabilizers),difficulty,category,aliases:split(aliases),instructions:execution.split(/(?<=\.) /),errors:families[pattern].errors,safety:families[pattern].safety,rom:families[pattern].rom,joints:families[pattern].joints,sourceIds:[...new Set([...split(primary),...split(secondary)].map(id=>groupById(id)?.sourceIds[0]).filter(Boolean)),'acsm2026'],unilateral:/single-leg|split-squat|lunge|step-up|^dumbbell-row|side-plank|bird-dog|external-rotation|hip-abduction|hip-adduction|band-leg-curl|cable-lateral-raise/.test(id),tracking:category==='cardio'?'duration-distance':pattern==='carry'?'duration-distance':['plank','side-plank'].includes(id)||category==='mobility'?'duration':'reps-load',objectives:category==='strength'?['strength','hypertrophy','general']:category==='mobility'?['mobility','general']:['endurance','general']}));
