export const anatomySources=[{id:'anatomy_upper',title:'Muscles of the pectoral girdle and upper limbs',authors:['OpenStax'],year:2022,url:'https://openstax.org/books/anatomy-and-physiology-2e/pages/11-5-muscles-of-the-pectoral-girdle-and-upper-limbs',type:'Anatomy educational reference',evidenceStrength:'Established anatomical descriptions; exercise attribution is qualitative',summary:'Anatomical joint actions inform the qualitative muscle relationships used in this app. A group highlight does not establish that all of its fibers contribute equally.',supportedClaims:['Shoulder, scapular and elbow actions.'],limitations:['Not an exercise activation study or validated segmented atlas.']},{id:'anatomy_lower',title:'Appendicular muscles of the pelvic girdle and lower limbs',authors:['OpenStax'],year:2022,url:'https://openstax.org/books/anatomy-and-physiology-2e/pages/11-6-appendicular-muscles-of-the-pelvic-girdle-and-lower-limbs',type:'Anatomy educational reference',evidenceStrength:'Established anatomical descriptions; exercise attribution is qualitative',summary:'Hip, knee and ankle actions inform exercise categories. Selectable superficial regions represent only some members of each anatomical muscle group.',supportedClaims:['Hip, knee and ankle actions.'],limitations:['Not an exercise activation study or validated segmented atlas.']},{id:'anatomy_axial',title:'Axial muscles of the abdominal wall and thorax',authors:['OpenStax'],year:2022,url:'https://openstax.org/books/anatomy-and-physiology-2e/pages/11-4-axial-muscles-of-the-abdominal-wall-and-thorax',type:'Anatomy educational reference',evidenceStrength:'Established anatomy',summary:'Trunk actions provide the anatomical basis for broad core and spinal-extensor categories. The app does not infer deep-muscle activation from superficial illustrations.',supportedClaims:['Abdominal and spinal muscle functions.'],limitations:['Deep muscles may have no selectable geometry.']}];
export const exerciseById=id=>exercises.find(e=>e.id===id);
// Word-by-word exercise search used by the Exercises page and the workout picker: every word must appear somewhere in the name, aliases, muscles, equipment or movement pattern, in any order. Common gym shorthand is expanded.
const SHORTHAND={db:'dumbbell',bb:'barbell',kb:'kettlebell',bw:'bodyweight',ohp:'overhead press',rdl:'romanian deadlift',shoulder:'deltoid',shoulders:'deltoid',delts:'deltoid',lats:'latissimus',abs:'abdominals',core:'abdominals',glutes:'gluteus',glute:'gluteus',quads:'quadriceps',hams:'hamstrings',biceps:'elbow flexors',bicep:'elbow flexors',tricep:'triceps'};
const queryWords=query=>String(query||'').toLowerCase().split(/\s+/).filter(Boolean).flatMap(w=>(SHORTHAND[w]||w).split(' '));
const groupNames=ids=>ids.map(g=>groupById(g)?.name||'').join(' ');
export function matchesQuery(e,query){const words=queryWords(query);if(!words.length)return true;const text=[e.name,...e.aliases,groupNames([...e.primary,...e.secondary]),...e.equipment.map(x=>equipmentLabels[x]||x),e.pattern.replaceAll('-',' ')].join(' ').toLowerCase();return words.every(w=>text.includes(w))}
// Matches first by name, then by main muscle, keeping library order otherwise.
export function searchExercises(list,query){const words=queryWords(query),found=list.filter(e=>matchesQuery(e,query));if(!words.length)return found;const score=e=>{const name=[e.name,...e.aliases].join(' ').toLowerCase(),primary=groupNames(e.primary).toLowerCase();return words.reduce((a,w)=>a+(name.includes(w)?2:0)+(primary.includes(w)?1:0),0)};return found.map((e,i)=>({e,i,s:score(e)})).sort((a,b)=>b.s-a.s||a.i-b.i).map(x=>x.e)}
export function alternatives(exercise,equipment=[]){return exercises.filter(e=>e.id!==exercise.id&&e.category===exercise.category&&e.primary.some(g=>exercise.primary.includes(g))&&((e.pattern===exercise.pattern&&e.pattern!=='isolation')||e.primary.join()===exercise.primary.join())&&(!equipment.length||e.equipment.every(x=>x==='bodyweight'||equipment.includes(x)))).sort((a,b)=>(b.pattern===exercise.pattern)-(a.pattern===exercise.pattern)).slice(0,6)}
